return ['x-generator'=>'GlotPress/4.0.1','translation-revision-date'=>'2023-01-08 03:58:32+0000','plural-forms'=>'nplurals=2; plural=n != 1;','project-id-version'=>'Plugins - Lightbox &amp; Modal Popup WordPress Plugin &#8211; FooBox - Stable (latest release)','language'=>'de','messages'=>['Creating image and video galleries has never been easier with our %s plugin, which works beautifully with FooBox!'=>'Das Erstellen von Bilder- und Videogalerien war noch nie so einfach mit unserem Plugin %s, das hervorragend mit FooBox funktioniert!','images within gallery and image blocks will open in FooBox (set Linked To -&gt; "Media File").'=>'Bilder innerhalb der Galerie und Bildblöcke werden in der FooBox geöffnet (setze Link zur -&gt; „Mediendatei“).','Gutenberg Editor'=>'Gutenberg-Editor','With 85+ settings available, you can customize FooBox to your heart\'s content.'=>'Mit über 85 verfügbaren Einstellungen kannst du FooBox ganz nach deinem Geschmack anpassen.','PLUS tons more!'=>'PLUS vieles mehr!','Power-users can add custom JS and CSS using our advanced settings.'=>'Fortgeschrittene Benutzer können individuelles JS und CSS über die erweiterten Einstellungen hinzufügen.','Custom JS &amp; CSS'=>'Individuelles JS &amp; CSS','JS &amp; CSS'=>'JS &amp; CSS','By default, FooBox includes javascript and stylesheet assets into all your pages. We do this, because we do not know if the page content contains media or not.<br>If you want more control over when FooBox assets are included, you can now exclude FooBox assets by default, by enabling this setting. Then on each page, you can choose to include the assets if required.<br>Or you can leave the setting disabled, and then choose to exclude FooBox assets from particular pages. A new FooBox metabox is now available when editing your pages or posts.'=>'Standardmäßig fügt FooBox JavaScript- und Stylesheet-Elemente in all deine Seiten ein. Wir tun dies, weil wir nicht wissen, ob der Seiteninhalt Medien enthält oder nicht.<br>Wenn du mehr Kontrolle darüber haben möchtest, wann FooBox solche Elemente einfügt, kannst du nun durch Aktivieren dieser Einstellung FooBox-Elemente standardmäßig ausschließen. Danach kannst du dann auf jeder Seite entscheiden, ob es erforderlich ist, die Elemente einzufügen.<br>Oder du kannst diese Einstellung deaktiviert lassen und dann entscheiden, FooBox-Elemente auf bestimmten Seiten auszuschließen. Beim Bearbeiten von Seiten und Beiträgen ist dafür nun eine neue FooBox-Metabox verfügbar.','Exclude FooBox Assets'=>'FooBox-Elemente ausschließen','Include FooBox on this page or post? By default, FooBox will be excluded!'=>'FooBox in diese Seite oder diesen Beitrag einfügen? Standardmäßig wird FooBox ausgeschlossen.','Exclude FooBox from this page or post? By default, FooBox will be included.'=>'FooBox von dieser Seite oder diesem Beitrag ausschließen? Standardmäßig wird FooBox eingefügt.','FooBox Javascript &amp; CSS'=>'FooBox JavaScript &amp; CSS','Activation'=>'Aktivierung','FooBox Opt-In'=>'FooBox Opt-In','Hide Captions'=>'Beschriftungen ausblenden','Whether or not to hide captions for images.'=>'Ob die Beschriftungen von Bildern ausgeblendet werden sollen.','the message to use as the item counter. The fields <code>%index</code> and <code>%total</code> can be used to substitute the correct values. <br/ >Example : <code>item %index / %total</code> would result in <code>item 1 / 7</code>'=>'Die Nachricht, die als Inhaltszähler angezeigt wird. Die Felder <code>%index</code> und <code>%total</code> können verwendet werden, um die entsprechenden Werte einzufügen. <br/ >Beispiel: <code>Bild %index / %total</code> würde zu <code>Bild 1 / 7</code> führen.','Count Message'=>'Zählungsnachricht','Start Your 7-day Free Trial'=>'Starte deine siebentägige Probephase','Want to test out all the PRO features? No problem! You can start a 7-day free trial immediately. No credit card is required!'=>'Willst du all unsere PRO-Funktionen ausprobieren? Kein Problem! Du kannst eine siebentägige Probephase sofort starten. Keine Kreditkarte erforderlich!','FooBox PRO Free Trial'=>'FooBox PRO Kostenlose Testversion','Already convinced? Upgrade to PRO!'=>'Bereits überzeugt? Upgrade auf PRO!','Upgrade to PRO'=>'Upgrade auf PRO','FooBox Image Lightbox'=>'FooBox Image Lightbox','Welcome to FooBox!'=>'Willkommen zu FooBox!','Settings'=>'Einstellungen','FooBox Settings'=>'FooBox-Einstellungen','FooBox'=>'FooBox','Getting Started With FooBox'=>'Erste Schritte mit FooBox','Free Trial'=>'Kostenlose Testversion','Download FooGallery'=>'Lade FooBox herunter','Looking for a Gallery Plugin?'=>'Auf der Suche nach einem Galerie-Plugin?','images found on pixabay.com'=>'Bilder gefunden auf Pixabay.com','A caption with no title, and only a long description describing the image'=>'Eine Beschriftung ohne Titel, nur mit einer langen Beschreibung des Bilds','Title With No Description'=>'Titel ohne Beschreibung','HTML is also <a href=\'#\'>allowed</a> in your <em>descriptions</em>!'=>'HTML ist ebenfalls <a href=\'#\'>erlaubt</a> in deinen <em>Beschreibungen</em>!','Beach Sandcastle'=>'Sandburg am Strand','You can have a nice long image description that goes here'=>'Du kannst schöne, lange Bildbeschreibungen einfügen, die hier erscheinen','Your Image Title Goes Here'=>'Dein Bildtitel erscheint hier','Use the browser\'s native fullscreen mode to showcase your media.'=>'Nutze den Vollbild-Modus des Browsers, um deine Medien zu präsentieren.','Fullscreen Mode'=>'Vollbild-Modus','Default, Metro and Flat styles available. You can also change color schemes and icons.'=>'Standard-, Metro- und Flat-Styles verfügbar. Ebenso kannst du Farbschemata und Symbole ändern.','Look and feel'=>'Erscheinungsbild','Share content to your favourite social networks with ease.'=>'Teile Inhalte mit Leichtigkeit auf deinen bevorzugten sozialen Netzwerken.','Social Sharing'=>'Teilen in Social Media','WP Gallery, FooGallery, Justified Image Grid, JetPack Tiled Gallery, NextGen Gallery, Envira Gallery, WooCommerce product images.'=>'WP Gallery, FooGallery, Justified Image Grid, JetPack Tiled Gallery, NextGen Gallery, Envira Gallery, WooCommerce Produkt-Abbildungen.','Supported Galleries'=>'Unterstützte Galerien','Images, galleries, videos, iframes, html. You name it, FooBox can open it.'=>'Bilder, Galerien, Videos, iFrames, HTML. Was immer du willst - FooBox kann es öffnen.','ALL content types'=>'ALLE Inhaltstypen','PRO Features'=>'PRO-Funktionen','open a captioned image'=>'Öffne ein beschriftetes Bild','FooBox will try to find captions from the link and image titles, but you can be sure by adding <strong>data-caption-title</strong> and <strong>data-caption-desc</strong> attributes onto your links, for example:'=>'FooBox sucht im Link und den Bildtiteln nach Beschriftungen. Aber um sicherzugehen, kannst du auch die Attribute <strong>data-caption-title</strong> und <strong>data-caption-desc</strong> deinen Links hinzufügen. Zum Beispiel:','Captions'=>'Beschriftungen','open a gallery'=>'Öffne eine Galerie','Group your images into galleries that open in FooBox. Just add the same rel attribute to the links you want to group together, for example:'=>'Gruppiere deine Bilder in Galerien, die sich in FooBox öffnen. Füge einfach das gleiche „rel“-Attribut den Links hinzu, die du zusammen gruppieren willst. Zum Beispiel:','rel="gallery"'=>'rel="gallery"','open an image'=>'Öffne ein Bild','Use your own links to open images in FooBox. Just add a class of "<strong>foobox</strong>" to your links, and make sure the link points to an image, for example:'=>'Nutze deine eigenen Links, um Bilder in FooBox zu öffnen. Füge einfach die Klasse <strong>FooBox</strong> deinen Links hinzu, und vergewissere dich, dass der Link zu einem Bild führt. Zum Beispiel:','class="foobox"'=>'class="foobox"','Visit the FooBox settings page'=>'Besuche die FooBox-Einstellungsseite','No configuration for the above is needed! But you can still customize the plugin from the settings page if you want to.'=>'Dafür ist keine Konfiguration erforderlich! Wenn du willst, kannst du aber das Plugin über die Einstellungsseite noch weiter anpassen.','images that are added using the "Add Media" tool.'=>'Bilder, die über den „Medien hinzufügen“-Button hinzugefügt werden.','image galleries that use the <code>[gallery]</code> shortcode.'=>'Bildergalerien, die den <code>[gallery]</code>-Shortcode verwenden.','images that use the <code>[caption]</code> shortcode.'=>'Bilder, die den <code>[caption]</code>-Shortcode verwenden.','Captioned Images'=>'Beschriftete Bilder','FooBox FREE works out-of-the-box with the following standard features:'=>'FooBox FREE funktioniert ohne Umwege mit den folgenden Standard-Funktionen:','Upgrade in WP Admin!'=>'Upgrade im WP-Adminpanel!','FooBox settings updated.'=>'FooBox-Einstellungen aktualisiert.','FooBox settings restored to defaults.'=>'FooBox-Einstellungen auf Standardwerte zurückgesetzt.','Support'=>'Unterstützung','Demo'=>'Demo','Zero Configuration'=>'Ohne Konfiguration','Getting Started'=>'Erste Schritte','Thank you for choosing FooBox as your lightbox! A great looking and responsive lightbox for your WordPress website!'=>'Danke, dass du dich für FooBox als deine Lightbox entschieden hast! Eine toll aussehende und responsive Lightbox für deine WordPress-Website!','http://fooplugins.com'=>'http://fooplugins.com','FooPlugins'=>'FooPlugins','The best responsive lightbox for WordPress.'=>'Die beste responsive Lightbox für WordPress','Restore Defaults'=>'Auf Standardwerte zurücksetzen','Are you sure you want to restore all settings back to their default values?'=>'Bist du sicher, dass du alle Einstellungen auf ihre Standardwerte zurücksetzen willst?','Save Changes'=>'Änderungen speichern','Settings restored to default values'=>'Einstellungen auf Standardwerte zurückgesetzt','Select An Image'=>'Wähle ein Bild',' Settings'=>'Einstellungen','There are tons of reasons...'=>'Es gibt eine Vielzahl von Gründen...','Upgrade to PRO!'=>'Upgrade auf PRO!','Debug Information'=>'Informationen zur Fehlersuche','Debug'=>'Fehlersuche','Show an extra debug information tab to help debug any issues.'=>'Zeigt einen zusätzlichen Fehlersuche-Informations-Tab zur Problembehandlung an.','Enable Debug Mode'=>'Fehlersuche-Modus aktivieren','Certain themes and plugins use a hard-coded lightbox, which make it very difficult to override.<br>By enabling this setting, we inject a small amount of javascript onto the page which attempts to get around this issue.<br>But please note this is not guaranteed, as we cannot account for every lightbox solution out there :)'=>'Manche Themes und Plugins verwenden fest eingebaute Lightboxen, was es sehr schwierig macht, diese außer Kraft zu setzen.<br>Durch Aktivieren dieser Einstellung fügen wir eine kleine Menge JavaScript auf der Seite ein, um dieses Problem zu umgehen.<br>Bitte beachte aber, dass wir dies nicht garantieren können, da wir nicht für jede erhältliche Lightbox-Lösung Verantwortung tragen können.','Disable Other Lightboxes'=>'Andere Lightboxen deaktivieren','Should the FooBox lightbox close when the overlay is clicked.'=>'Ob sich die FooBox-Lightbox schließen soll, wenn die Überlagerung angeklickt wird.','Close On Overlay Click'=>'Schließen bei Klick auf Überlagerung','Advanced'=>'Erweitert','Could not load the item'=>'Inhalt konnte nicht geladen werden','The error message to display when an image has trouble loading.'=>'Die angezeigte Fehlermeldung, wenn ein Bild nicht geladen werden konnte.','Error Message'=>'Fehlermeldung','Only show the caption when hovering over the image.'=>'Die Beschriftungen nur anzeigen, wenn sich die Maus über dem Bild befindet.','Show Captions On Hover'=>'Beschriftungen bei Mauszeigerkontakt anzeigen','Shows a counter under the FooBox modal when viewing a gallery of images.'=>'Zeigt beim Betrachten einer Bildergalerie einen Zähler unterhalb der FooBox-Einblendung.','Show Counter'=>'Zähler anzeigen','Hide the page\'s scrollbars when FooBox is visible.'=>'Blendet die Bildlaufleisten der Seite aus, wenn FooBox sichtbar ist.','Hide Page Scrollbars'=>'Seiten-Bildlaufleisten ausblenden','Force smaller images to fit the screen dimensions.'=>'Erzwingt das Anpassen kleiner Bilder an die Bildschirm-Abmessungen.','Fit To Screen'=>'An Bildschirm anpassen','Display Settings'=>'Anzeigeeinstellungen','Enable FooBox for all media images included in posts or pages.'=>'Aktiviert FooBox für alle Bilder in Beiträgen oder Seiten.','Attachment Images'=>'Angehängte Bilder','Enable FooBox for all WordPress images that have captions.'=>'Aktiviert FooBox für alle WordPress-Bilder, die Beschriftungen haben.','WordPress Images With Captions'=>'WordPress-Bilder mit Beschriftungen','Enable FooBox for all WordPress image galleries.'=>'Aktiviert FooBox für alle WordPress-Bildergalerien.','WordPress Galleries'=>'WordPress-Galerien','What do you want to attach FooBox to?'=>'Womit willst du FooBox verknüpfen?','General'=>'Allgemein','http://fooplugins.com/foobox/'=>'http://fooplugins.com/foobox/','Select Image'=>'Bild auswählen']];